package com.deliverysaas.drivers;
import com.deliverysaas.audit.AuditService;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.deliverysaas.drivers.domain.*;import com.deliverysaas.shared.error.*;import com.deliverysaas.shared.security.AuthPrincipal;import com.deliverysaas.users.domain.UserRole;
@Service public class DriverLocationService{private final DriverRepository drivers;private final DriverLocationRepository locations;private final AuditService audit;public DriverLocationService(DriverRepository d,DriverLocationRepository l,AuditService a){drivers=d;locations=l;audit=a;}@Transactional public DriverLocationResponse create(AuthPrincipal p,CreateDriverLocationRequest r){if(p.role()!=UserRole.DRIVER)throw new ForbiddenException("Driver role required");Driver d=drivers.findByUserIdAndUserOrganizationId(p.userId(),p.organizationId()).orElseThrow(()->new NotFoundException("Driver not found"));DriverLocation location=locations.save(new DriverLocation(d,r.latitude(),r.longitude()));audit.record("CREATE","DRIVER_LOCATION",location.getId(),"Driver location recorded");return DriverLocationResponse.from(location);}@Transactional(readOnly=true)public List<DriverLocationResponse> all(AuthPrincipal p,UUID id){Driver d=get(p,id);return locations.findAllByDriverIdOrderByRecordedAtDesc(d.getId()).stream().map(DriverLocationResponse::from).toList();}@Transactional(readOnly=true)public DriverLocationResponse latest(AuthPrincipal p,UUID id){Driver d=get(p,id);return locations.findFirstByDriverIdOrderByRecordedAtDesc(d.getId()).map(DriverLocationResponse::from).orElseThrow(()->new NotFoundException("Driver location not found"));}private Driver get(AuthPrincipal p,UUID id){Driver d=drivers.findByIdAndUserOrganizationId(id,p.organizationId()).orElseThrow(()->new NotFoundException("Driver not found"));if(p.role()==UserRole.DRIVER&&!d.getUser().getId().equals(p.userId()))throw new NotFoundException("Driver not found");if(p.role()==UserRole.CUSTOMER)throw new ForbiddenException("You cannot access driver locations");return d;}}
